CREATE OR REPLACE FUNCTION parse_logtime(text) RETURNS date AS $$
BEGIN
    IF $1 ~ '^\d{4}-\d{2}-\d{2}$' THEN
        RETURN CAST($1 AS DATE);
    ELSIF $1 ~ '^\d{4}/\d{2}/\d{2}$' THEN
        RETURN CAST(REPLACE($1, '/', '-') AS DATE);
    ELSIF $1 ~ '(st|nd|rd|th),' THEN
        RETURN CAST(to_timestamp(regexp_replace($1, '(st|nd|rd|th)', '', 'g'), 'Month DD, YYYY') AS DATE);
    ELSIF length(split_part($1, ' ', 1)) <= 3 THEN
        RETURN CAST(to_timestamp($1, 'Mon DD, YYYY') AS DATE);
    ELSE
        RETURN CAST(to_timestamp($1, 'Month DD, YYYY') AS DATE);
    END IF;
END;
$$ LANGUAGE plpgsql;
